#!/usr/bin/env python3
"""Compact ENEM question generator for years 2009-2012."""
import json, os, sys

os.makedirs("data", exist_ok=True)

def build_file(year, questions):
    """Write a year's questions to JSON file."""
    with open(f"data/{year}.json", "w", encoding="utf-8") as f:
        json.dump(questions, f, ensure_ascii=False, indent=2)
    # Count per area
    counts = {}
    for q in questions:
        a = q["area"]
        counts[a] = counts.get(a, 0) + 1
    return counts

# Helper: generate questions from compact tuples
# Format: (disc, ctx, text, pergunta, [5 opts], gab, dif, taxa)
def make_questions(year, area, qlist):
    prefix = {"linguagens":"L","humanas":"H","natureza":"N","matematica":"M"}[area]
    result = []
    for i, (disc, ctx, text, pergunta, opts, gab, dif, taxa) in enumerate(qlist, 1):
        result.append({
            "id": f"{prefix}{year}_{i:02d}",
            "ano": year,
            "area": area,
            "disciplina": disc,
            "contexto": ctx,
            "texto": text,
            "pergunta": pergunta,
            "opcoes": opts,
            "gabarito": gab,
            "dificuldade": dif,
            "taxaAcerto": taxa
        })
    return result

# We'll generate each year separately with distinct content
# For brevity, we generate 2009 first, then adapt for other years

def gen_year(year):
    questions = []
    seq = 0
    
    def add(area, disc, ctx, text, pergunta, opts, gab, dif, taxa):
        nonlocal seq
        seq += 1
        prefix = {"linguagens":"L","humanas":"H","natureza":"N","matematica":"M"}[area]
        questions.append({
            "id": f"{prefix}{year}_{seq:02d}",
            "ano": year,
            "area": area,
            "disciplina": disc,
            "contexto": ctx,
            "texto": text,
            "pergunta": pergunta,
            "opcoes": opts,
            "gabarito": gab,
            "dificuldade": dif,
            "taxaAcerto": taxa
        })
    
    return add, questions

def gen_2009():
    add, qs = gen_year(2009)
    
